# Task-only hashed edit manifest. Removed before exact-head validation.
import base64,hashlib,json,lzma,pathlib
rows=json.loads(lzma.decompress(base64.b64decode("")))
for row in rows:
 p=pathlib.Path(row['path'])
 assert p.exists()==row['exists'],row['path']
 old=p.read_text() if p.exists() else ''
 assert hashlib.sha256(old.encode()).hexdigest()==row['before'],row['path']+' base drift'
 for lo,hi,text in reversed(row['edits']):old=old[:lo]+text+old[hi:]
 assert hashlib.sha256(old.encode()).hexdigest()==row['after'],row['path']+' output mismatch'
 p.parent.mkdir(parents=True,exist_ok=True);p.write_text(old)
